		if (bp[0] & 0xfc)
			ND_PRINT((ndo, " [rsvd=0x%02x]", bp[0] & 0xfc));
		bp += 1;
		len -= 1;
		if (len < 1)
			goto trunc;
		ND_TCHECK(bp[0]);
		nentries = bp[0];
		bp += 1;
		len -= 1;
 		s = ' ';
 		for (; nentries; nentries--) {
			if (len < 6)
				goto trunc;
 			ND_TCHECK2(bp[0], 6);
